-- Complete finance core tables that were previously referenced by the UI but
-- absent from the live project. All DDL is idempotent.
CREATE TABLE IF NOT EXISTS public.customers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, vkn_tckn TEXT, authorized_person TEXT, phone TEXT NOT NULL DEFAULT '', email TEXT, address TEXT, tax_office TEXT, balance NUMERIC DEFAULT 0, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.sites (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, customer_id UUID REFERENCES public.customers(id) ON DELETE CASCADE, customer_name TEXT, location TEXT, contact_person TEXT, phone TEXT, status TEXT NOT NULL DEFAULT 'aktif', created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.job_receipts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), receipt_no TEXT NOT NULL UNIQUE, customer_id UUID REFERENCES public.customers(id) ON DELETE RESTRICT, customer_name TEXT NOT NULL, site_id UUID REFERENCES public.sites(id) ON DELETE SET NULL, site_name TEXT, crane_code TEXT NOT NULL DEFAULT '', operator_id UUID REFERENCES public.personnel(id) ON DELETE SET NULL, operator_name TEXT NOT NULL DEFAULT '', date DATE NOT NULL DEFAULT CURRENT_DATE, start_time TEXT, end_time TEXT, working_hours NUMERIC DEFAULT 0, description TEXT, lines JSONB DEFAULT '[]'::jsonb, amount NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending_approval', invoiced BOOLEAN NOT NULL DEFAULT FALSE, invoice_id UUID, invoice_no TEXT, approved_by TEXT, approved_at TIMESTAMPTZ, rejected_by TEXT, rejected_at TIMESTAMPTZ, rejection_reason TEXT, note TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_no TEXT NOT NULL UNIQUE, customer_id UUID REFERENCES public.customers(id) ON DELETE RESTRICT, customer_name TEXT NOT NULL, receipt_ids UUID[] DEFAULT ARRAY[]::UUID[], issue_date DATE NOT NULL DEFAULT CURRENT_DATE, due_date DATE NOT NULL DEFAULT CURRENT_DATE, subtotal NUMERIC NOT NULL DEFAULT 0, tax_rate NUMERIC NOT NULL DEFAULT 20, tax_amount NUMERIC NOT NULL DEFAULT 0, total_amount NUMERIC NOT NULL DEFAULT 0, paid_amount NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft', notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.collections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_id UUID REFERENCES public.customers(id) ON DELETE CASCADE, customer_name TEXT NOT NULL, invoice_id UUID REFERENCES public.invoices(id) ON DELETE SET NULL, invoice_no TEXT, amount NUMERIC NOT NULL DEFAULT 0, due_date DATE, date DATE NOT NULL DEFAULT CURRENT_DATE, payment_method TEXT NOT NULL DEFAULT 'havale', status TEXT NOT NULL DEFAULT 'bekliyor', notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), recipient_type TEXT NOT NULL DEFAULT 'tedarikci', recipient_id UUID, recipient_name TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'diger', amount NUMERIC NOT NULL DEFAULT 0, due_date DATE NOT NULL DEFAULT CURRENT_DATE, paid_date DATE, payment_date DATE, payment_method TEXT DEFAULT 'havale', status TEXT NOT NULL DEFAULT 'bekliyor', payroll_item_id UUID, notes TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
